### Implementation Code

#### 1. Distributed Tracing & Logging Subsystem

This subsystem implements W3C trace propagation standards and handles correlation tracking. It maps correlation contexts to both incoming and outgoing request/response streams and bridges them into the ASP.NET Core logging context.

```csharp
namespace CloudNative.ApiGateway.Tracing;

using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using System.Diagnostics;

public static class TracingConstants
{
    public const string CorrelationIdHeader = "X-Correlation-ID";
    public const string TraceParentHeader = "traceparent";
    public const string TraceStateHeader = "tracestate";
}

public sealed class DistributedTracingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<DistributedTracingMiddleware> _logger;

    public DistributedTracingMiddleware(RequestDelegate next, ILogger<DistributedTracingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // 1. Try to resolve existing Correlation ID or generate a new structured ID
        string correlationId = GetOrGenerateCorrelationId(context);

        // 2. Set correlation ID in HttpContext.Items for internal gateway propagation
        context.Items[TracingConstants.CorrelationIdHeader] = correlationId;

        // 3. Ensure correlation ID is returned to the client in the response headers
        context.Response.OnStarting(() =>
        {
            if (!context.Response.Headers.ContainsKey(TracingConstants.CorrelationIdHeader))
            {
                context.Response.Headers.Append(TracingConstants.CorrelationIdHeader, correlationId);
            }
            return Task.CompletedTask;
        });

        // 4. Enrich Structured Logs with logging scopes for distributed tracing correlation
        var logScope = new Dictionary<string, object>
        {
            ["CorrelationId"] = correlationId,
            ["TraceId"] = Activity.Current?.TraceId.ToString() ?? context.TraceIdentifier
        };

        using (_logger.BeginScope(logScope))
        {
            _logger.LogInformation("Processing gateway request: {Method} {Path}", context.Request.Method, context.Request.Path);
            await _next(context);
            _logger.LogInformation("Finished gateway request processing with Status Code: {StatusCode}", context.Response.StatusCode);
        }
    }

    private static string GetOrGenerateCorrelationId(HttpContext context)
    {
        if (context.Request.Headers.TryGetValue(TracingConstants.CorrelationIdHeader, out var correlationId) && 
            !string.IsNullOrWhiteSpace(correlationId))
        {
            return correlationId.ToString();
        }

        // Fallback to W3C Trace context TraceId if available, otherwise generate new hierarchical ID
        return Activity.Current?.TraceId.ToString() ?? Guid.NewGuid().ToString("N");
    }
}
```

