#### 2. Cryptographic JWT Authentication & Fine-Grained Authorization

This module implements cryptographic validation of downstream Bearer tokens (using asymmetric **RS256** signatures) and features a high-performance authorization policy engine designed for granular OIDC/OAuth2 scope validation.

```csharp
namespace CloudNative.ApiGateway.Security;

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.IdentityModel.Tokens;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Http;
using System.Text.Json;

public static class SecurityConfigurationExtensions
{
    public static IServiceCollection AddGatewaySecurity(this IServiceCollection services, RSA publicKey)
    {
        // Configure Cryptographic Token Authentication using RS256 Asymmetric Key
        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
            options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
        })
        .AddJwtBearer(options =>
        {
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new RsaSecurityKey(publicKey),
                ValidateIssuer = true,
                ValidIssuer = "https://identity.cloudnative-gateway.internal",
                ValidateAudience = true,
                ValidAudience = "cloudnative-api-gateway",
                ValidateLifetime = true,
                ClockSkew = TimeSpan.FromSeconds(30),
                CryptoProviderFactory = new CryptoProviderFactory { CacheSignatureProviders = true }
            };

            options.Events = new JwtBearerEvents
            {
                OnChallenge = async context =>
                {
                    context.HandleResponse();
                    context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                    context.Response.ContentType = "application/json";

                    var payload = JsonSerializer.Serialize(new { 
                        error = "unauthorized", 
                        message = "Missing, invalid, or expired cryptographic token." 
                    });
                    await context.Response.WriteAsync(payload);
                }
            };
        });

        // Register custom Authorization requirement and handler for OAuth2 Scopes
        services.AddSingleton<IAuthorizationHandler, ScopeRequirementHandler>();

        return services;
    }
}

public sealed class ScopeRequirement : IAuthorizationRequirement
{
    public string RequiredScope { get; }

    public ScopeRequirement(string requiredScope)
    {
        ArgumentException.ThrowIfNullOrEmpty(requiredScope);
        RequiredScope = requiredScope;
    }
}

public sealed class ScopeRequirementHandler : AuthorizationHandler<ScopeRequirement>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, ScopeRequirement requirement)
    {
        if (context.User == null)
        {
            return Task.CompletedTask;
        }

        // Read standard OIDC scope claims (handles both 'scope' and 'scp' claims structures)
        var scopeClaims = context.User.FindAll(c => c.Type == "scope" || c.Type == "scp")
                                     .SelectMany(c => c.Value.Split(' ', StringSplitOptions.RemoveEmptyEntries))
                                     .ToHashSet(StringComparer.Ordinal);

        if (scopeClaims.Contains(requirement.RequiredScope))
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}
```

