#### 3. High-Performance Dynamic Reverse Proxy (YARP) Engine

Implements dynamic routing and cluster topologies using standard .NET configurations, decorated with custom tracing transform providers. This ensures correlation tracking IDs map cleanly across outgoing network sockets.

```csharp
namespace CloudNative.ApiGateway.Proxy;

using Yarp.ReverseProxy.Configuration;
using Yarp.ReverseProxy.Transforms;
using CloudNative.ApiGateway.Tracing;

public static class DynamicProxyConfiguration
{
    public static IReadOnlyList<RouteConfig> GetRoutes()
    {
        return new[]
        {
            new RouteConfig
            {
                RouteId = "catalog-route",
                RoutePattern = "api/v1/catalog/{**catch-all}",
                ClusterId = "catalog-cluster",
                AuthorizationPolicy = "CatalogReadPolicy",
                Metadata = new Dictionary<string, string> { { "RequiresScope", "catalog.read" } }
            },
            new RouteConfig
            {
                RouteId = "orders-route",
                RoutePattern = "api/v1/orders/{**catch-all}",
                ClusterId = "orders-cluster",
                AuthorizationPolicy = "OrdersWritePolicy",
                Metadata = new Dictionary<string, string> { { "RequiresScope", "orders.write" } }
            }
        };
    }

    public static IReadOnlyList<ClusterConfig> GetClusters()
    {
        return new[]
        {
            new ClusterConfig
            {
                ClusterId = "catalog-cluster",
                Destinations = new Dictionary<string, DestinationConfig>(StringComparer.OrdinalIgnoreCase)
                {
                    { "catalog-node-1", new DestinationConfig { Address = "http://catalog-service.internal:8081" } }
                }
            },
            new ClusterConfig
            {
                ClusterId = "orders-cluster",
                Destinations = new Dictionary<string, DestinationConfig>(StringComparer.OrdinalIgnoreCase)
                {
                    { "orders-node-1", new DestinationConfig { Address = "http://orders-service.internal:8082" } }
                }
            }
        };
    }
}

/// <summary>
/// Implements high-throughput runtime context transforms injecting tracing data into outgoing downstream proxy sockets.
/// </summary>
public sealed class GatewayTracingTransformProvider : ITransformProvider
{
    public void ValidateRoute(TransformRouteValidationContext context) { }

    public void ValidateCluster(TransformClusterValidationContext context) { }

    public void Apply(TransformBuilderContext context)
    {
        context.AddRequestTransform(transformContext =>
        {
            var httpContext = transformContext.HttpContext;

            // Extract Correlation ID from internal request tracking scope
            if (httpContext.Items.TryGetValue(TracingConstants.CorrelationIdHeader, out var correlationObj) && 
                correlationObj is string correlationId)
            {
                // Inject Correlation ID into outgoing downstream microservice request headers
                transformContext.ProxyRequest.Headers.Remove(TracingConstants.CorrelationIdHeader);
                transformContext.ProxyRequest.Headers.TryAddWithoutValidation(TracingConstants.CorrelationIdHeader, correlationId);
            }

            // Forward W3C Distributed Context Trace Headers if available
            var currentActivity = System.Diagnostics.Activity.Current;
            if (currentActivity != null)
            {
                transformContext.ProxyRequest.Headers.Remove(TracingConstants.TraceParentHeader);
                transformContext.ProxyRequest.Headers.TryAddWithoutValidation(TracingConstants.TraceParentHeader, currentActivity.Id);

                if (currentActivity.TraceStateString != null)
                {
                    transformContext.ProxyRequest.Headers.Remove(TracingConstants.TraceStateHeader);
                    transformContext.ProxyRequest.Headers.TryAddWithoutValidation(TracingConstants.TraceStateHeader, currentActivity.TraceStateString);
                }
            }

            return ValueTask.CompletedTask;
        });
    }
}
```

