#### 4. Unified Composition Root (`Program.cs`)

This acts as the composition bootstrapper, wiring up routing tables, asymmetric encryption keys, policies, authentication contexts, and the custom processing pipeline.

```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System.Security.Cryptography;
using CloudNative.ApiGateway.Tracing;
using CloudNative.ApiGateway.Security;
using CloudNative.ApiGateway.Proxy;

var builder = WebApplication.CreateBuilder(args);

// 1. Generate / Configure Cryptographic Keys (RS256)
// Note: For multi-instance deployments, extract this from Key Vault, AWS Secrets Manager, or a dynamic JWKS endpoint.
var rsaKey = RSA.Create(2048); 

// For demonstration purposes, we serialize the public and private keys to output in the logs
// so you can generate valid tokens instantly for checking out-of-the-box system compliance.
var publicParameters = rsaKey.ExportParameters(false);
var privateParameters = rsaKey.ExportParameters(true);

// 2. Setup Logging Subsystem
builder.Services.AddLogging(loggingBuilder =>
{
    loggingBuilder.AddSimpleConsole(options =>
    {
        options.IncludeScopes = true;
        options.SingleLine = true;
        options.TimestampFormat = "[HH:mm:ss] ";
    });
});

// 3. Setup Core Cryptographic Security Policies
builder.Services.AddGatewaySecurity(rsaKey);

builder.Services.AddAuthorization(options =>
{
    // Programmatic mapping of Scopes based on Route Constraints
    options.AddPolicy("CatalogReadPolicy", policy =>
        policy.RequireAuthenticatedUser()
              .AddRequirements(new ScopeRequirement("catalog.read")));

    options.AddPolicy("OrdersWritePolicy", policy =>
        policy.RequireAuthenticatedUser()
              .AddRequirements(new ScopeRequirement("orders.write")));
});

// 4. Register Dynamic YARP Core Engine with Distributed Tracing transforms
builder.Services.AddReverseProxy()
    .LoadFromMemory(DynamicProxyConfiguration.GetRoutes(), DynamicProxyConfiguration.GetClusters())
    .AddTransformProvider<GatewayTracingTransformProvider>();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}

// 5. Build Pipeline Execution Order (Tracing -> Auth -> Routing)
app.UseMiddleware<DistributedTracingMiddleware>();

app.UseRouting();

app.UseAuthentication();
app.UseAuthorization();

app.MapReverseProxy();

// Write startup operational indicators
var logger = app.Services.GetRequiredService<ILogger<Program>>();
logger.LogInformation("==========================================================");
logger.LogInformation("Cloud-Native High Performance API Gateway Initialized.");
logger.LogInformation("Cryptographic Signature Schema: RS256 (RSA-SHA256)");
logger.LogInformation("Dynamic Clusters Configured: catalog-cluster, orders-cluster");
logger.LogInformation("Distributed Tracing engine loaded.");
logger.LogInformation("==========================================================");

// Expose verification endpoint for testing the system configurations locally
app.MapGet("/dev/token", (IWebHostEnvironment env) =>
{
    if (!env.IsDevelopment()) return Results.NotFound();

    // Generate valid development token mapped directly to Gateway's internal Key
    var token = GenerateDevToken(rsaKey);
    return Results.Ok(new { access_token = token, token_type = "Bearer" });
});

app.Run();

// Helper method for bootstrapping manual testing & runtime verification
static string GenerateDevToken(RSA rsa)
{
    using var rsaForSigning = RSA.Create(rsa.ExportParameters(true));
    var securityKey = new Microsoft.IdentityModel.Tokens.RsaSecurityKey(rsaForSigning);
    var credentials = new Microsoft.IdentityModel.Tokens.SigningCredentials(securityKey, Microsoft.IdentityModel.Tokens.SecurityAlgorithms.RsaSha256);

    var header = new System.IdentityModel.Tokens.Jwt.JwtHeader(credentials);
    var payload = new System.IdentityModel.Tokens.Jwt.JwtPayload(
        issuer: "https://identity.cloudnative-gateway.internal",
        audience: "cloudnative-api-gateway",
        claims: new[] 
        { 
            new System.Security.Claims.Claim("scope", "catalog.read orders.write"),
            new System.Security.Claims.Claim("sub", "user_102910")
        },
        notBefore: DateTime.UtcNow,
        expires: DateTime.UtcNow.AddHours(2)
    );

    var token = new System.IdentityModel.Tokens.Jwt.JwtSecurityToken(header, payload);
    return new System.IdentityModel.Tokens.Jwt.JwtSecurityTokenHandler().WriteToken(token);
}
